class Solution:
    def shortestBridge(self, grid: list[list[int]]) -> int:
        from collections import deque
        n = len(grid)
        visited = [[False]*n for _ in range(n)]
        queue = deque()

        def dfs(r, c):
            if r < 0 or r >= n or c < 0 or c >= n or visited[r][c] or grid[r][c] == 0:
                return
            visited[r][c] = True
            queue.append((r, c, 0))
            dfs(r+1,c)
            dfs(r-1,c)
            dfs(r,c+1)
            dfs(r,c-1)

        found = False
        for i in range(n):
            if found:
                break
            for j in range(n):
                if grid[i][j] == 1:
                    dfs(i, j)
                    found = True
                    break

        while queue:
            r, c, d = queue.popleft()
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                    if grid[nr][nc] == 1:
                        return d
                    visited[nr][nc] = True
                    queue.append((nr, nc, d+1))
        return -1

